package de.g3connect.maps;
import java.util.*;
import java.security.MessageDigest;
import javax.crypto.Cipher;
import javax.crypto.spec.SecretKeySpec;
import java.io.ByteArrayOutputStream;
/** Independently implemented Encryption2; counter is shared across both directions. */
final class NinebotCrypto {
 static final byte[] FW=unhex("97cfb802844143de56002b3b34780a5d");
 byte[] auth=new byte[16]; boolean session; int counter,lastRx=-1; private Cipher aes;
 void key(byte[] a,byte[] b)throws Exception {byte[] input=new byte[32];System.arraycopy(a,0,input,0,Math.min(16,a.length));System.arraycopy(b,0,input,16,Math.min(16,b.length));aes=Cipher.getInstance("AES/ECB/NoPadding");aes.init(Cipher.ENCRYPT_MODE,new SecretKeySpec(Arrays.copyOf(MessageDigest.getInstance("SHA-1").digest(input),16),"AES"));}
 private byte[] block(byte[] a)throws Exception{return aes.doFinal(a);}
 private byte[] nonce(int n){byte[] b=new byte[13];b[0]=(byte)(n>>>24);b[1]=(byte)(n>>>16);b[2]=(byte)(n>>>8);b[3]=(byte)n;System.arraycopy(auth,0,b,4,8);return b;}
 private byte[] ctr(byte[] nonce,int index){byte[] b=new byte[16];b[0]=1;System.arraycopy(nonce,0,b,1,13);b[15]=(byte)index;return b;}
 private byte[] crypt(byte[] payload,byte[] nonce)throws Exception{byte[] out=new byte[payload.length];for(int p=0,i=1;p<payload.length;p+=16,i++){byte[] stream=block(nonce==null?FW:ctr(nonce,i));for(int j=0;j<16&&p+j<payload.length;j++)out[p+j]=(byte)(payload[p+j]^stream[j]);}return out;}
 private byte[] tag(byte[] plain,byte[] nonce)throws Exception {byte[] b=new byte[16];b[0]=0x59;System.arraycopy(nonce,0,b,1,13);b[15]=(byte)(plain.length-3);byte[] x=block(b);Arrays.fill(b,(byte)0);System.arraycopy(plain,0,b,0,3);x=block(xor(x,b));for(int p=3;p<plain.length;p+=16){b=new byte[16];System.arraycopy(plain,p,b,0,Math.min(16,plain.length-p));x=block(xor(x,b));}return Arrays.copyOf(xor(x,block(ctr(nonce,0))),4);}
 byte[] encrypt(byte[] plain)throws Exception {byte[] p=Arrays.copyOfRange(plain,3,plain.length),out=new byte[plain.length+6];System.arraycopy(plain,0,out,0,3);int n=0;if(session){if(counter>=65535)throw new IllegalStateException("Sitzungszähler voll. Neu verbinden.");n=++counter;}byte[] nonce=session?nonce(n):null;System.arraycopy(crypt(p,nonce),0,out,3,p.length);if(session){System.arraycopy(tag(plain,nonce),0,out,out.length-6,4);}else{int sum=0;for(byte v:p)sum+=v&255;sum=~sum&65535;out[out.length-4]=(byte)sum;out[out.length-3]=(byte)(sum>>>8);}out[out.length-2]=(byte)(n>>>8);out[out.length-1]=(byte)n;return out;}
 byte[] decrypt(byte[] raw)throws Exception {int len=raw.length;if(len<13||len!=(raw[2]&255)+13||(raw[0]&255)!=0x5a||((raw[1]&255)!=0xa5&&(raw[1]&255)!=0xb5))throw new IllegalArgumentException("Ungültiger Frame.");int n=((raw[len-2]&255)<<8)|(raw[len-1]&255);if(n==0&&session||n!=0&&(!session||n<=lastRx))throw new IllegalArgumentException("Unerwarteter Sitzungszähler.");byte[] p=crypt(Arrays.copyOfRange(raw,3,len-6),n==0?null:nonce(n));byte[] plain=new byte[len-6];System.arraycopy(raw,0,plain,0,3);System.arraycopy(p,0,plain,3,p.length);int diff=0;if(n==0){int sum=0;for(byte v:p)sum+=v&255;sum=~sum&65535;diff=(raw[len-6]&255)|(raw[len-5]&255)|((raw[len-4]&255)^(sum&255))|((raw[len-3]&255)^(sum>>>8));}else{byte[] t=tag(plain,nonce(n));for(int i=0;i<4;i++)diff|=t[i]^raw[len-6+i];}if(diff!=0)throw new SecurityException("Antwort nicht authentifiziert.");if(n!=0){lastRx=n;counter=Math.max(counter,n);}return plain;}
 static byte[] frame(int board,int cmd,int index,byte[] payload){if(payload.length>255)throw new IllegalArgumentException();byte[] b=new byte[7+payload.length];b[0]=0x5a;b[1]=(byte)0xa5;b[2]=(byte)payload.length;b[3]=0x3e;b[4]=(byte)board;b[5]=(byte)cmd;b[6]=(byte)index;System.arraycopy(payload,0,b,7,payload.length);return b;}
 private static byte[] xor(byte[] a,byte[] b){byte[] c=a.clone();for(int i=0;i<c.length;i++)c[i]^=b[i];return c;}
 static byte[] unhex(String s){if(s==null||!s.matches("(?:[0-9a-fA-F]{2})+"))throw new IllegalArgumentException();byte[] b=new byte[s.length()/2];for(int i=0;i<b.length;i++)b[i]=(byte)Integer.parseInt(s.substring(i*2,i*2+2),16);return b;}
 static String hex(byte[] b){StringBuilder s=new StringBuilder();for(byte x:b)s.append(String.format(java.util.Locale.ROOT,"%02x",x&255));return s.toString();}
 static final class Frames {private byte[] buffer=new byte[0];List<byte[]> push(byte[] chunk){ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(buffer,0,buffer.length);out.write(chunk,0,chunk.length);buffer=out.toByteArray();List<byte[]> frames=new ArrayList<>();while(buffer.length>0){int i=0;while(i+1<buffer.length&&!((buffer[i]&255)==0x5a&&((buffer[i+1]&255)==0xa5||(buffer[i+1]&255)==0xb5)))i++;if(i+1>=buffer.length){buffer=buffer[buffer.length-1]==0x5a?new byte[]{0x5a}:new byte[0];break;}buffer=Arrays.copyOfRange(buffer,i,buffer.length);if(buffer.length<3)break;int size=13+(buffer[2]&255);if(buffer.length<size)break;frames.add(Arrays.copyOf(buffer,size));buffer=Arrays.copyOfRange(buffer,size,buffer.length);}return frames;}}
}
